import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Proxies, DNS Blocking, VPNs, and National Firewalls","description":"","frontmatter":{},"headers":[],"relativePath":"networking/proxies_vpn/ProxiesVpnFirewalls.md","filePath":"networking/proxies_vpn/ProxiesVpnFirewalls.md"}'),r={name:"networking/proxies_vpn/ProxiesVpnFirewalls.md"};function i(n,e,l,c,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="proxies-dns-blocking-vpns-and-national-firewalls" tabindex="-1">Proxies, DNS Blocking, VPNs, and National Firewalls <a class="header-anchor" href="#proxies-dns-blocking-vpns-and-national-firewalls" aria-label="Permalink to &quot;Proxies, DNS Blocking, VPNs, and National Firewalls&quot;">​</a></h1><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="proxy-fundamentals" tabindex="-1">Proxy fundamentals <a class="header-anchor" href="#proxy-fundamentals" aria-label="Permalink to &quot;Proxy fundamentals&quot;">​</a></h3><p>A proxy is a middleman that receives a request and forwards it elsewhere:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ─► Proxy ─► Server</span></span></code></pre></div><p>The key questions: <strong>who is the proxy representing, and who is being hidden?</strong> That gives the two major types.</p><h3 id="forward-proxy-—-hides-clients" tabindex="-1">Forward proxy — hides clients <a class="header-anchor" href="#forward-proxy-—-hides-clients" aria-label="Permalink to &quot;Forward proxy — hides clients&quot;">​</a></h3><p>Represents the <strong>client</strong>; the destination server sees the proxy, not the original client.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Employee laptop ─► Corporate proxy ─► Google</span></span></code></pre></div><p>Typical uses: corporate internet filtering, website access restrictions, privacy, VPN-like behavior.</p><h3 id="reverse-proxy-—-hides-servers" tabindex="-1">Reverse proxy — hides servers <a class="header-anchor" href="#reverse-proxy-—-hides-servers" aria-label="Permalink to &quot;Reverse proxy — hides servers&quot;">​</a></h3><p>Represents the <strong>server</strong>; users communicate with the reverse proxy and never directly reach backend servers.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User ─► Reverse proxy ─► [Server A | B | C | D]</span></span></code></pre></div><h3 id="why-reverse-proxies-exist" tabindex="-1">Why reverse proxies exist <a class="header-anchor" href="#why-reverse-proxies-exist" aria-label="Permalink to &quot;Why reverse proxies exist&quot;">​</a></h3><ul><li><strong>Security</strong> — backend servers stay private, not directly reachable from the internet.</li><li><strong>Load balancing</strong> — distribute requests across servers (req1 → A, req2 → B, ...).</li><li><strong>Caching</strong> — frequently requested content served from the proxy, reducing backend load.</li><li><strong>SSL/TLS termination</strong> — the proxy handles HTTPS and certificates; backends don&#39;t perform TLS processing themselves.</li></ul><h3 id="reverse-proxy-vs-load-balancer-vs-cdn" tabindex="-1">Reverse proxy vs load balancer vs CDN <a class="header-anchor" href="#reverse-proxy-vs-load-balancer-vs-cdn" aria-label="Permalink to &quot;Reverse proxy vs load balancer vs CDN&quot;">​</a></h3><p>Many modern <strong>load balancers are effectively reverse proxies</strong> — they receive the request and forward it to a backend, which is reverse-proxy behavior. <strong>CDN edge servers also behave like reverse proxies</strong>: receive request → check cache → forward misses to origin.</p><h3 id="gateway-vs-reverse-proxy" tabindex="-1">Gateway vs reverse proxy <a class="header-anchor" href="#gateway-vs-reverse-proxy" aria-label="Permalink to &quot;Gateway vs reverse proxy&quot;">​</a></h3><p>A reverse proxy is the <strong>narrower</strong> concept — its primary job is hiding backend servers and controlling traffic to them. A gateway is <strong>broader</strong>: it may add API management, authentication, policy enforcement, protocol translation.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reverse proxy ⊂ Gateway</span></span></code></pre></div><p>A reverse proxy can be viewed as a specialized type of gateway.</p><h2 id="dns-resolution-and-blocking" tabindex="-1">DNS resolution and blocking <a class="header-anchor" href="#dns-resolution-and-blocking" aria-label="Permalink to &quot;DNS resolution and blocking&quot;">​</a></h2><p>The browser can&#39;t communicate using a domain name — DNS translates <code>google.com</code> → <code>142.x.x.x</code>. Most users automatically use their ISP&#39;s DNS resolver (laptop → Airtel DNS → returns IP). (Full resolution flow: <code>networking/dns/DnsResolution.md</code>.)</p><h3 id="dns-blocking" tabindex="-1">DNS blocking <a class="header-anchor" href="#dns-blocking" aria-label="Permalink to &quot;DNS blocking&quot;">​</a></h3><p>For a blocked site, the ISP&#39;s resolver responds with <strong>&quot;not found,&quot; &quot;blocked,&quot; or a fake IP</strong> — the user never gets the correct IP, so the connection never starts.</p><h3 id="why-changing-dns-sometimes-works" tabindex="-1">Why changing DNS sometimes works <a class="header-anchor" href="#why-changing-dns-sometimes-works" aria-label="Permalink to &quot;Why changing DNS sometimes works&quot;">​</a></h3><p>Pointing the laptop at an external resolver (e.g. Google DNS) may return the real IP, bypassing the block — but <strong>only when blocking exists solely at the DNS layer</strong>.</p><h3 id="ip-blocking" tabindex="-1">IP blocking <a class="header-anchor" href="#ip-blocking" aria-label="Permalink to &quot;IP blocking&quot;">​</a></h3><p>The ISP/government can drop packets destined for specific IPs. Even with correct DNS (<code>badsite.com → 123.45.67.89</code>), packets to that IP are dropped — changing DNS no longer helps.</p><h2 id="vpn-internals" tabindex="-1">VPN internals <a class="header-anchor" href="#vpn-internals" aria-label="Permalink to &quot;VPN internals&quot;">​</a></h2><h3 id="without-vpn" tabindex="-1">Without VPN <a class="header-anchor" href="#without-vpn" aria-label="Permalink to &quot;Without VPN&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You ─► ISP ─► Website</span></span></code></pre></div><p>The ISP sees <code>destination IP = website</code> and can apply blocking.</p><h3 id="with-vpn" tabindex="-1">With VPN <a class="header-anchor" href="#with-vpn" aria-label="Permalink to &quot;With VPN&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You ─► encrypted tunnel ─► VPN server ─► Website</span></span></code></pre></div><p>The ISP sees only <code>destination IP = VPN server</code>; the final destination is hidden inside the encrypted tunnel.</p><ul><li><strong>Bypasses DNS blocking:</strong> DNS queries travel <em>inside</em> the tunnel to the VPN&#39;s DNS — the ISP cannot inspect or modify them.</li><li><strong>Bypasses IP blocking:</strong> the ISP only sees the VPN server&#39;s IP; the VPN server connects to the blocked site <em>outside</em> the ISP&#39;s network.</li></ul><h2 id="national-firewall-architecture" tabindex="-1">National firewall architecture <a class="header-anchor" href="#national-firewall-architecture" aria-label="Permalink to &quot;National firewall architecture&quot;">​</a></h2><h3 id="traditional-isp-based-blocking" tabindex="-1">Traditional ISP-based blocking <a class="header-anchor" href="#traditional-isp-based-blocking" aria-label="Permalink to &quot;Traditional ISP-based blocking&quot;">​</a></h3><p>Each ISP (Airtel/Jio/BSNL) independently implements blocking rules between users and the internet.</p><h3 id="national-firewall-model" tabindex="-1">National firewall model <a class="header-anchor" href="#national-firewall-model" aria-label="Permalink to &quot;National firewall model&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Users → ISPs → national filtering infrastructure → global internet</span></span></code></pre></div><p>Most international traffic passes through centralized filtering — one highly controlled national checkpoint instead of many separate ones.</p><h3 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th></tr></thead><tbody><tr><td>DNS filtering</td><td>Return fake or invalid DNS responses</td></tr><tr><td>IP blocking</td><td>Drop traffic to specific destinations</td></tr><tr><td>Deep packet inspection (DPI)</td><td>Inspect packet metadata and protocol characteristics — can detect VPN traffic, certain applications, suspicious patterns</td></tr><tr><td>VPN detection</td><td>Identify and block common VPN protocols (OpenVPN, WireGuard)</td></tr><tr><td>Active probing</td><td>The firewall itself connects to a suspected VPN server to test whether it runs VPN software; if confirmed, it&#39;s blocked</td></tr></tbody></table><h2 id="gotchas-trick-questions" tabindex="-1">Gotchas / Trick questions <a class="header-anchor" href="#gotchas-trick-questions" aria-label="Permalink to &quot;Gotchas / Trick questions&quot;">​</a></h2><ol><li><strong>&quot;Reverse proxy and gateway are basically the same.&quot;</strong> Not exactly — reverse proxy is narrower (protect/abstract backends); gateway is broader (API management, auth, policy, protocol translation).</li><li><strong>&quot;The primary purpose of a reverse proxy is load balancing.&quot;</strong> Not quite — the core purpose is acting as the intermediary in front of backend servers; load balancing is one capability built on that position.</li><li><strong>&quot;Changing DNS always bypasses website blocking.&quot;</strong> False — it only defeats DNS-level blocking. With IP blocking, a DNS change is ineffective.</li><li><strong>&quot;DNS is a global system — how can my ISP block it?&quot;</strong> Your device typically queries the <em>ISP&#39;s</em> resolver, which the ISP controls. The block happens at the resolver level.</li><li><strong>&quot;A VPN magically makes blocked websites accessible.&quot;</strong> The VPN doesn&#39;t remove the block — the ISP sees only the VPN, and the VPN sees the website. The ISP never sees the final destination.</li><li><strong>&quot;If VPN traffic is encrypted, it can never be blocked.&quot;</strong> False — VPNs themselves are detected and blocked via known VPN IP lists, DPI, and active probing.</li><li><strong>&quot;Servers behind a reverse proxy are hidden because they&#39;re backups.&quot;</strong> No — they may be primary, active, load-balanced servers. They&#39;re hidden because the proxy sits in front of them, not because they&#39;re failovers.</li></ol><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><h3 id="the-blocking-escalation-ladder" tabindex="-1">The blocking escalation ladder <a class="header-anchor" href="#the-blocking-escalation-ladder" aria-label="Permalink to &quot;The blocking escalation ladder&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DNS blocking → IP blocking → DPI → VPN detection → national-scale filtering</span></span></code></pre></div><p>Each layer is progressively harder to bypass. Many countries restrict through ISPs; some run centralized systems resembling national firewalls.</p><h3 id="why-this-is-mostly-beyond-sde2" tabindex="-1">Why this is mostly beyond SDE2 <a class="header-anchor" href="#why-this-is-mostly-beyond-sde2" aria-label="Permalink to &quot;Why this is mostly beyond SDE2&quot;">​</a></h3><p>For a typical SDE2 system design interview, this is sufficient: <em>DNS resolves domain → IP; VPN creates an encrypted tunnel; reverse proxy sits in front of servers.</em> Deep DPI/national-firewall/VPN-detection knowledge is networking/security-engineering territory — but understanding it sharpens intuition around DNS, TLS, proxies, gateways, CDNs, and traffic flow.</p><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Forward proxy vs reverse proxy?</strong> A. Forward proxy hides clients; reverse proxy hides servers.</p><p><strong>Q. Why use a reverse proxy?</strong> A. Security, load balancing, caching, SSL termination, request routing.</p><p><strong>Q. Why does changing DNS sometimes bypass blocking — and sometimes not?</strong> A. It defeats DNS-resolver-level blocks only; IP-level blocking still drops the packets.</p><p><strong>Q. What does a VPN hide from the ISP?</strong> A. The final destination website and the DNS queries (both travel inside the encrypted tunnel).</p><p><strong>Q. Can VPNs themselves be blocked?</strong> A. Yes — VPN IP blacklists, deep packet inspection, and active probing.</p><p><strong>Q. Reverse proxy vs gateway?</strong> A. Reverse proxy ⊂ gateway — the gateway adds API management, auth, policy enforcement, protocol translation.</p>',60)])])}const b=t(r,[["render",i]]);export{g as __pageData,b as default};
